#include <iostream>
#include <bit>
#include <atcoder/modint>

int main() {
    using namespace std;
    using modint = atcoder::static_modint<998244353>;
    unsigned long N, M;
    cin >> N >> M;
    ++N;
    modint ans{};
    while(N){
        const auto i{N & -N};
        ans += modint::raw(popcount(M & N - i) + popcount(M & N - 1)) * i;
        N ^= i;
    }
    cout << (ans / 2).val() << endl;
    return 0;
}
